const tabId = 1962625075;
const hepaticSection = await browserjs(tabId, () => {
  const h4s = Array.from(document.querySelectorAll('h4'));
  const hepaticH4 = h4s.find(h => h.textContent.includes('hepatic dysfunction'));
  if (!hepaticH4) return null;

  let current = hepaticH4;
  const elements = [current.outerHTML];
  while (current.nextElementSibling && current.nextElementSibling.tagName !== 'H4' && current.nextElementSibling.tagName !== 'H3') {
    current = current.nextElementSibling;
    elements.push(current.outerHTML);
  }
  return {
    rawHtml: elements.join('\n'),
    text: elements.map(html => {
      const div = document.createElement('div');
      div.innerHTML = html;
      return div.innerText;
    }).join('\n\n')
  };
});

